import type { ReactNode } from 'react';
import { cx } from '@/lib/cx';
import './accordion.css';

/**
 * B27 · Accordion — native <details>/<summary>. One list of sections that
 * open in place. It hides SECONDARY detail; it never hides the primary
 * job of a screen, and it is never navigation (that is the Band).
 */
export interface AccordionSection {
  id: string;
  title: string;
  /** Mono metadata rendered right of the title — a count, a date, a status. */
  meta?: ReactNode;
  children: ReactNode;
  defaultOpen?: boolean;
}

export interface AccordionProps {
  sections: AccordionSection[];
  /**
   * One open at a time (native `name` grouping). Omit for independent
   * sections — the default, because closing a section the reader opened
   * is a surprise.
   */
  exclusive?: boolean;
  /** Required when exclusive: the shared native group name. */
  name?: string;
  className?: string;
}

export function Accordion({ sections, exclusive = false, name, className }: AccordionProps) {
  return (
    <div className={cx('sv-accordion', className)}>
      {sections.map((section) => (
        <details
          key={section.id}
          className="sv-accordion__item"
          name={exclusive ? (name ?? 'sv-accordion') : undefined}
          open={section.defaultOpen}
        >
          <summary className="sv-accordion__summary">
            <span className="sv-accordion__chevron" aria-hidden="true" />
            <span className="sv-accordion__title">{section.title}</span>
            {section.meta != null && <span className="sv-accordion__meta sv-mono">{section.meta}</span>}
          </summary>
          <div className="sv-accordion__panel">{section.children}</div>
        </details>
      ))}
    </div>
  );
}

/* B27 · Accordion — native <details>. Hairline rows, no card of its own. */

@layer sv-components {
  .sv-accordion__item {
    border-top: 1px solid var(--sv-line);
  }

  .sv-accordion__item:last-child {
    border-bottom: 1px solid var(--sv-line);
  }

  .sv-accordion__summary {
    display: flex;
    align-items: center;
    gap: var(--sv-s2);
    padding: var(--sv-s3) 0;
    cursor: pointer;
    list-style: none;
  }

  .sv-accordion__summary::-webkit-details-marker {
    display: none;
  }

  .sv-accordion__summary:focus-visible {
    outline: 2px solid var(--sv-seed-line);
    outline-offset: 2px;
  }

  .sv-accordion__title {
    font-size: 13px;
    font-weight: 600;
    color: var(--sv-ink);
  }

  .sv-accordion__meta {
    margin-left: auto;
    font-size: 10.5px;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--sv-ink-soft);
  }

  /* Drawn from borders, not an icon font — the open state is also carried
     by the panel itself, so the chevron is supplementary (C5). */
  .sv-accordion__chevron {
    flex-shrink: 0;
    width: 6px;
    height: 6px;
    border-right: 1.5px solid var(--sv-ink-soft);
    border-bottom: 1.5px solid var(--sv-ink-soft);
    transform: rotate(-45deg);
    transition: transform var(--sv-t-fast);
  }

  .sv-accordion__item[open] .sv-accordion__chevron {
    transform: rotate(45deg);
  }

  .sv-accordion__panel {
    padding: 0 0 var(--sv-s4) 14px;
    font-size: 13px;
    line-height: 1.55;
    color: var(--sv-ink-soft);
  }

  /* ---- v0.9 · the panel fades, and the row does NOT slide ---------

     What every accordion animates is the height, and 76° cannot: A1
     forbids transitioning layout outright, and the firewall greps for
     it. That ban is not a gap this rule works around — a height
     transition on a <details> pushes every row below it down for the
     length of the animation, so the reader who went to click the next
     section watches it walk away from the pointer. The rows snap, which
     is what they do today and what they will keep doing.

     What is left is honest and is the part worth having: the panel's
     copy fades up over 120ms while the row is already at its final
     height, so the section reads as opening rather than as replaced.
     Opacity only — no transform, because a 6px rise inside a box that
     just snapped open is two events where the reader saw one.

     Not posture-gated: <details> opens because the reader clicked the
     summary, so this is feedback on an act (dialog.css argues the
     boundary in full) and `--sv-t-fast` collapses at the token layer
     under reduced motion and on paper. The chevron above already runs
     ungated on the same step; a panel that held still under a chevron
     that turned would be two rules about one click. */
  .sv-accordion__item[open] .sv-accordion__panel {
    animation: sv-accordion-open var(--sv-t-fast) cubic-bezier(0.215, 0.61, 0.355, 1);
  }

  @keyframes sv-accordion-open {
    from {
      opacity: 0;
    }
  }
}
